response_text:
Here is a complete, modular, and production-grade Distributed SQL Query Execution Engine implemented in C#. 

This implementation is self-contained, using modern asynchronous patterns (`async`/`await`, `System.Threading.Channels`), custom binary network protocols over TCP/IP sockets, and a custom **Grace Hash Aggregation** algorithm that gracefully handles memory constraints via dynamic disk partitioning and spilling.

### Architectural Overview

```
                        ┌──────────────────────────────────────┐
                        │        Input Data Generator          │
                        └──────────────────┬───────────────────┘
                                           │
                                           ▼
                        ┌──────────────────────────────────────┐
                        │       ExchangeWriteOperator          │
                        │   (Partitioning & TCP Serialization) │
                        └──────┬────────────────────────┬──────┘
                               │                        │
                    (Node 1 - TCP Stream)      (Node 2 - TCP Stream)
                               │                        │
                               ▼                        ▼
                        ┌──────────────────────────────────────┐
                        │       ExchangeReadOperator           │
                        │     (Multiplexed TCP Server)         │
                        └──────────────────┬───────────────────┘
                                           │ (Record Batches)
                                           ▼
                        ┌──────────────────────────────────────┐
                        │    GraceHashAggregationOperator     │
                        └──────┬────────────────────────┬──────┘
                               │                        │
                      (Within Memory)            (Memory Exceeded)
                               │                        │
                               ▼                        ▼
                        ┌──────────────┐         ┌──────────────┐
                        │ AggregateMap │         │  Disk Spill  │
                        │ (In-Memory)  │         │   Manager    │
                        └──────┬───────┘         └──────┬───────┘
                               │                        │
                               └───────────┬────────────┘
                                           │ (Merged Streams)
                                           ▼
                        ┌──────────────────────────────────────┐
                        │          Aggregated Results          │
                        └──────────────────────────────────────┘
```

---

### Modern C# Implementation

Create a new console application (`dotnet new console`) and replace `Program.cs` with the following comprehensive code:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

namespace DistributedSqlEngine
{
    #region 1. Core Data Models & Binary Serialization

    public enum DataType : byte
    {
        Int = 0,
        Double = 1,
        String = 2
    }

    public record Field(string Name, DataType Type);

    public class Schema
    {
        public List<Field> Fields { get; }

        public Schema(List<Field> fields)
        {
            Fields = fields ?? throw new ArgumentNullException(nameof(fields));
        }

        public int GetFieldIndex(string name)
        {
            int index = Fields.FindIndex(f => f.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
            if (index == -1)
                throw new ArgumentException($"Field '{name}' not found in schema.");
            return index;
        }
    }

    public class Record
    {
        public object[] Values { get; }

        public Record(object[] values)
        {
            Values = values ?? throw new ArgumentNullException(nameof(values));
        }
    }

    public class RecordBatch
    {
        public Schema Schema { get; }
        public List<Record> Records { get; }

        public RecordBatch(Schema schema, List<Record> records)
        {
            Schema = schema ?? throw new ArgumentNullException(nameof(schema));
            Records = records ?? throw new ArgumentNullException(nameof(records));
        }
    }

    public static class BinarySerializer
    {
        public static void WriteSchema(BinaryWriter writer, Schema schema)
        {
            writer.Write((int)schema.Fields.Count);
            foreach (var field in schema.Fields)
            {
                writer.Write(field.Name);
                writer.Write((byte)field.Type);
            }
        }

        public static Schema ReadSchema(BinaryReader reader)
        {
            int count = reader.ReadInt32();
            var fields = new List<Field>(count);
            for (int i = 0; i < count; i++)
            {
                string name = reader.ReadString();
                DataType type = (DataType)reader.ReadByte();
                fields.Add(new Field(name, type));
            }
            return new Schema(fields);
        }

        public static void WriteRecord(BinaryWriter writer, Record record, Schema schema)
        {
            for (int i = 0; i < schema.Fields.Count; i++)
            {
                var val = record.Values[i];
                if (val == null)
                {
                    writer.Write(false); // Null flag
                    continue;
                }
                writer.Write(true);
                switch (schema.Fields[i].Type)
                {
                    case DataType.Int:
                        writer.Write((int)val);
                        break;
                    case DataType.Double:
                        writer.Write((double)val);
                        break;
                    case DataType.String:
                        writer.Write((string)val);
                        break;
                }
            }
        }

        public static Record ReadRecord(BinaryReader reader, Schema schema)
        {
            var values = new object[schema.Fields.Count];
            for (int i = 0; i < schema.Fields.Count; i++)
            {
                bool isNotNull = reader.ReadBoolean();
                if (!isNotNull)
                {
                    values[i] = null;
                    continue;
                }
                switch (schema.Fields[i].Type)
                {
                    case DataType.Int:
                        values[i] = reader.ReadInt32();
                        break;
                    case DataType.Double:
                        values[i] = reader.ReadDouble();
                        break;
                    case DataType.String:
                        values[i] = reader.ReadString();
                        break;
                }
            }
            return new Record(values);
        }

        public static byte[] SerializeBatch(RecordBatch batch)
        {
            using var ms = new MemoryStream();
            using (var writer = new BinaryWriter(ms, Encoding.UTF8, leaveOpen: true))
            {
                WriteSchema(writer, batch.Schema);
                writer.Write(batch.Records.Count);
                foreach (var record in batch.Records)
                {
                    WriteRecord(writer, record, batch.Schema);
                }
            }
            return ms.ToArray();
        }

        public static RecordBatch DeserializeBatch(byte[] bytes)
        {
            using var ms = new MemoryStream(bytes);
            using var reader = new BinaryReader(ms, Encoding.UTF8);
            var schema = ReadSchema(reader);
            int recordCount = reader.ReadInt32();
            var records = new List<Record>(recordCount);
            for (int i = 0; i < recordCount; i++)
            {
                records.Add(ReadRecord(reader, schema));
            }
            return new RecordBatch(schema, records);
        }
    }

    #endregion

    #region 2. Network Exchange Operator

    public static class NetworkFrameProtocol
    {
        public const byte MsgSchema = 1;
        public const byte MsgDataBatch = 2;
        public const byte MsgEof = 3;

        public static async Task SendMessageAsync(NetworkStream stream, byte messageType, byte[] payload)
        {
            byte[] lengthHeader = BitConverter.GetBytes(payload.Length);
            await stream.WriteAsync(lengthHeader, 0, 4);
            stream.WriteByte(messageType);
            if (payload.Length > 0)
            {
                await stream.WriteAsync(payload, 0, payload.Length);
            }
            await stream.FlushAsync();
        }

        public static async Task<(byte MsgType, byte[] Payload)> ReadMessageAsync(NetworkStream stream, CancellationToken token = default)
        {
            byte[] lengthHeader = new byte[4];
            int readBytes = 0;
            while (readBytes < 4)
            {
                int read = await stream.ReadAsync(lengthHeader, readBytes, 4 - readBytes, token);
                if (read == 0) throw new EndOfStreamException("Client connection dropped prematurely.");
                readBytes += read;
            }

            int length = BitConverter.ToInt32(lengthHeader, 0);
            int msgTypeByte = stream.ReadByte();
            if (msgTypeByte == -1) throw new EndOfStreamException("Missing stream control flag.");

            byte[] payload = new byte[length];
            readBytes = 0;
            while (readBytes < length)
            {
                int read = await stream.ReadAsync(payload, readBytes, length - readBytes, token);
                if (read == 0) throw new EndOfStreamException("Incomplete framing payload stream.");
                readBytes += read;
            }

            return ((byte)msgTypeByte, payload);
        }
    }

    public class ExchangeWriteOperator
    {
        private readonly List<IPEndPoint> _destinations;
        private readonly string _partitionKeyColumn;
        private readonly Dictionary<IPEndPoint, TcpClient> _clients = new();
        private readonly Dictionary<IPEndPoint, NetworkStream> _streams = new();

        public ExchangeWriteOperator(List<IPEndPoint> destinations, string partitionKeyColumn)
        {
            _destinations = destinations ?? throw new ArgumentNullException(nameof(destinations));
            _partitionKeyColumn = partitionKeyColumn ?? throw new ArgumentNullException(nameof(partitionKeyColumn));
        }

        public async Task ConnectAllAsync()
        {
            foreach (var ep in _destinations)
            {
                var client = new TcpClient();
                await client.ConnectAsync(ep.Address, ep.Port);
                _clients[ep] = client;
                _streams[ep] = client.GetStream();
            }
        }

        public async Task PushBatchAsync(RecordBatch batch)
        {
            int keyIndex = batch.Schema.GetFieldIndex(_partitionKeyColumn);
            var partitionBuckets = _destinations.Select(_ => new List<Record>()).ToArray();

            foreach (var record in batch.Records)
            {
                var val = record.Values[keyIndex];
                int hash = val?.GetHashCode() ?? 0;
                int routeIndex = Math.Abs(hash) % _destinations.Count;
                partitionBuckets[routeIndex].Add(record);
            }

            for (int i = 0; i < _destinations.Count; i++)
            {
                if (partitionBuckets[i].Count == 0) continue;

                var routeBatch = new RecordBatch(batch.Schema, partitionBuckets[i]);
                byte[] data = BinarySerializer.SerializeBatch(routeBatch);
                var stream = _streams[_destinations[i]];
                await NetworkFrameProtocol.SendMessageAsync(stream, NetworkFrameProtocol.MsgDataBatch, data);
            }
        }

        public async Task CloseAsync()
        {
            foreach (var ep in _destinations)
            {
                if (_streams.TryGetValue(ep, out var stream))
                {
                    await NetworkFrameProtocol.SendMessageAsync(stream, NetworkFrameProtocol.MsgEof, Array.Empty<byte>());
                    stream.Close();
                }
                if (_clients.TryGetValue(ep, out var client))
                {
                    client.Close();
                }
            }
        }
    }

    public class ExchangeReadOperator : IDisposable
    {
        private readonly TcpListener _listener;
        private readonly Channel<RecordBatch> _bufferChannel;
        private readonly int _expectedSenders;
        private int _connectedSenders = 0;
        private readonly CancellationTokenSource _cts = new();
        private Task _acceptorTask;

        public ChannelReader<RecordBatch> Reader => _bufferChannel.Reader;

        public ExchangeReadOperator(int port, int expectedSenders)
        {
            _listener = new TcpListener(IPAddress.Loopback, port);
            _bufferChannel = Channel.CreateUnbounded<RecordBatch>(new UnboundedChannelOptions
            {
                SingleReader = true,
                SingleWriter = false
            });
            _expectedSenders = expectedSenders;
        }

        public void Start()
        {
            _listener.Start();
            _acceptorTask = Task.Run(AcceptLoopAsync);
            Console.WriteLine($"[Network] Exchange Server listening on port {_listener.LocalEndpoint}");
        }

        private async Task AcceptLoopAsync()
        {
            var connectionTasks = new List<Task>();
            try
            {
                for (int i = 0; i < _expectedSenders; i++)
                {
                    var tcpClient = await _listener.AcceptTcpClientAsync(_cts.Token);
                    Interlocked.Increment(ref _connectedSenders);
                    connectionTasks.Add(Task.Run(() => HandleIncomingClientAsync(tcpClient)));
                }
                await Task.WhenAll(connectionTasks);
            }
            catch (OperationCanceledException) { }
            catch (Exception ex)
            {
                _bufferChannel.Writer.TryComplete(ex);
            }
            finally
            {
                _bufferChannel.Writer.TryComplete();
            }
        }

        private async Task HandleIncomingClientAsync(TcpClient client)
        {
            using (client)
            using (var stream = client.GetStream())
            {
                try
                {
                    while (!_cts.Token.IsCancellationRequested)
                    {
                        var (type, payload) = await NetworkFrameProtocol.ReadMessageAsync(stream, _cts.Token);
                        if (type == NetworkFrameProtocol.MsgEof)
                        {
                            break;
                        }
                        else if (type == NetworkFrameProtocol.MsgDataBatch)
                        {
                            var batch = BinarySerializer.DeserializeBatch(payload);
                            await _bufferChannel.Writer.WriteAsync(batch, _cts.Token);
                        }
                    }
                }
                catch (Exception ex) when (ex is IOException || ex is EndOfStreamException)
                {
                    // Clean connection loss
                }
                finally
                {
                    if (Interlocked.Decrement(ref _connectedSenders) == 0)
                    {
                        _bufferChannel.Writer.TryComplete();
                    }
                }
            }
        }

        public void Dispose()
        {
            _cts.Cancel();
            _listener.Stop();
            _bufferChannel.Writer.TryComplete();
        }
    }

    #endregion

    #region 3. Disk Spill Manager

    public class MemoryTracker
    {
        private long _allocatedBytes = 0;
        public long BytesAllocated => Interlocked.Read(ref _allocatedBytes);

        public void Allocate(long size) => Interlocked.Add(ref _allocatedBytes, size);
        public void Deallocate(long size) => Interlocked.Add(ref _allocatedBytes, -size);

        public static long EstimateValueMemory(object value)
        {
            if (value == null) return 8;
            if (value is string s) return 24 + (s.Length * 2);
            if (value is double) return 8;
            if (value is int) return 4;
            return 16;
        }

        public static long EstimateRecordSize(Record rec)
        {
            long accum = 16; // Record wrapper size
            foreach (var v in rec.Values)
            {
                accum += EstimateValueMemory(v);
            }
            return accum;
        }
    }

    public class DiskSpillEntry
    {
        public bool IsPartialAggregate { get; }
        public AggregateKey Key { get; }
        public object[] States { get; }
        public Record RawRecord { get; }

        public DiskSpillEntry(AggregateKey key, object[] states)
        {
            IsPartialAggregate = true;
            Key = key;
            States = states;
        }

        public DiskSpillEntry(Record rawRecord)
        {
            IsPartialAggregate = false;
            RawRecord = rawRecord;
        }
    }

    public class DiskSpillManager : IDisposable
    {
        private readonly string _spillDirectory;
        private readonly Dictionary<int, FileStream> _writeStreams = new();
        private readonly Dictionary<int, BinaryWriter> _writers = new();

        public DiskSpillManager()
        {
            _spillDirectory = Path.Combine(Path.GetTempPath(), $"DistributedSpill_{Guid.NewGuid():N}");
            Directory.CreateDirectory(_spillDirectory);
            Console.WriteLine($"[Spill] Disk workspace initialized at: {_spillDirectory}");
        }

        private void EnsurePartitionWriter(int partitionId)
        {
            if (!_writeStreams.ContainsKey(partitionId))
            {
                var filePath = Path.Combine(_spillDirectory, $"partition_{partitionId}.spill");
                var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.Read, 65536);
                _writeStreams[partitionId] = fs;
                _writers[partitionId] = new BinaryWriter(fs, Encoding.UTF8);
            }
        }

        public void SpillEntry(int partitionId, DiskSpillEntry entry, Schema keySchema, Schema valSchema)
        {
            EnsurePartitionWriter(partitionId);
            var writer = _writers[partitionId];

            writer.Write(entry.IsPartialAggregate);
            if (entry.IsPartialAggregate)
            {
                // Write structural aggregate Key
                BinarySerializer.WriteRecord(writer, new Record(entry.Key.Values), keySchema);

                // Write state counts & states dynamically
                writer.Write(entry.States.Length);
                foreach (var state in entry.States)
                {
                    if (state is double d)
                    {
                        writer.Write((byte)DataType.Double);
                        writer.Write(d);
                    }
                    else if (state is long l)
                    {
                        writer.Write((byte)DataType.Int); // Packed count or numeric mapping
                        writer.Write(l);
                    }
                    else
                    {
                        writer.Write((byte)DataType.String);
                        writer.Write(state?.ToString() ?? string.Empty);
                    }
                }
            }
            else
            {
                BinarySerializer.WriteRecord(writer, entry.RawRecord, valSchema);
            }
        }

        public void FlushPartition(int partitionId)
        {
            if (_writers.TryGetValue(partitionId, out var writer))
            {
                writer.Flush();
            }
        }

        public IEnumerable<DiskSpillEntry> StreamPartition(int partitionId, Schema keySchema, Schema rawSchema)
        {
            // Close active writers to release lock
            if (_writers.TryGetValue(partitionId, out var writer))
            {
                writer.Close();
                _writers.Remove(partitionId);
            }
            if (_writeStreams.TryGetValue(partitionId, out var stream))
            {
                stream.Close();
                _writeStreams.Remove(partitionId);
            }

            var filePath = Path.Combine(_spillDirectory, $"partition_{partitionId}.spill");
            if (!File.Exists(filePath)) yield break;

            using var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 65536);
            using var reader = new BinaryReader(fs, Encoding.UTF8);

            while (fs.Position < fs.Length)
            {
                bool isPartial = reader.ReadBoolean();
                if (isPartial)
                {
                    var keyRec = BinarySerializer.ReadRecord(reader, keySchema);
                    var key = new AggregateKey(keyRec.Values);
                    int statesCount = reader.ReadInt32();
                    var states = new object[statesCount];
                    for (int i = 0; i < statesCount; i++)
                    {
                        DataType type = (DataType)reader.ReadByte();
                        states[i] = type switch
                        {
                            DataType.Double => reader.ReadDouble(),
                            DataType.Int => reader.ReadInt64(), // Reads long state representation
                            DataType.String => reader.ReadString(),
                            _ => throw new InvalidDataException("Corrupted spill data type marker.")
                        };
                    }
                    yield return new DiskSpillEntry(key, states);
                }
                else
                {
                    var rawRecord = BinarySerializer.ReadRecord(reader, rawSchema);
                    yield return new DiskSpillEntry(rawRecord);
                }
            }
        }

        public void Dispose()
        {
            foreach (var writer in _writers.Values) writer.Dispose();
            foreach (var fs in _writeStreams.Values) fs.Dispose();
            try
            {
                if (Directory.Exists(_spillDirectory))
                {
                    Directory.Delete(_spillDirectory, true);
                    Console.WriteLine("[Spill] Workspace cleaned from storage.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[Spill Warning] Failed to delete temp workspace: {ex.Message}");
            }
        }
    }

    #endregion

    #region 4. Hash Aggregation Operator (Grace Hash Aggregation)

    public class AggregateKey
    {
        public object[] Values { get; }
        private readonly int _cachedHash;

        public AggregateKey(object[] values)
        {
            Values = values ?? throw new ArgumentNullException(nameof(values));
            int hash = 17;
            foreach (var val in values)
            {
                hash = hash * 31 + (val?.GetHashCode() ?? 0);
            }
            _cachedHash = hash;
        }

        public override bool Equals(object obj)
        {
            if (obj is not AggregateKey other) return false;
            if (Values.Length != other.Values.Length) return false;
            for (int i = 0; i < Values.Length; i++)
            {
                if (!Equals(Values[i], other.Values[i])) return false;
            }
            return true;
        }

        public override int GetHashCode() => _cachedHash;
    }

    public enum AggregateType
    {
        Sum,
        Count
    }

    public record AggregateDefinition(string TargetField, AggregateType Type, string Alias);

    public interface IAggregateFunction
    {
        void Update(object val);
        void Merge(object state);
        object GetState();
        object Compute();
        IAggregateFunction Clone();
    }

    public class SumAggregate : IAggregateFunction
    {
        private double _sum = 0.0;
        public void Update(object val) { if (val != null) _sum += Convert.ToDouble(val); }
        public void Merge(object state) { if (state != null) _sum += Convert.ToDouble(state); }
        public object GetState() => _sum;
        public object Compute() => _sum;
        public IAggregateFunction Clone() => new SumAggregate();
    }

    public class CountAggregate : IAggregateFunction
    {
        private long _count = 0;
        public void Update(object val) { _count++; }
        public void Merge(object state) { if (state != null) _count += Convert.ToInt64(state); }
        public object GetState() => _count;
        public object Compute() => _count;
        public IAggregateFunction Clone() => new CountAggregate();
    }

    public class HashAggregationOperator
    {
        private class PartitionBucket
        {
            public int PartitionId { get; }
            public Dictionary<AggregateKey, List<IAggregateFunction>> MemoryMap { get; set; } = new();
            public bool IsSpilled { get; set; } = false;
            public long BytesEstimated { get; set; } = 0;

            public PartitionBucket(int id) => PartitionId = id;
        }

        private readonly List<string> _groupByKeys;
        private readonly List<AggregateDefinition> _aggDefinitions;
        private readonly MemoryTracker _memoryTracker;
        private readonly DiskSpillManager _spillManager;
        private readonly long _maxMemoryBytes;

        private const int PartitionCount = 8;
        private readonly PartitionBucket[] _partitions = new PartitionBucket[PartitionCount];

        private Schema _inputSchema;
        private Schema _keySchema;
        private Schema _outputSchema;

        private int[] _keyIndices;
        private int[] _aggIndices;

        public HashAggregationOperator(
            List<string> groupByKeys,
            List<AggregateDefinition> aggDefinitions,
            MemoryTracker memoryTracker,
            DiskSpillManager spillManager,
            long maxMemoryBytes)
        {
            _groupByKeys = groupByKeys;
            _aggDefinitions = aggDefinitions;
            _memoryTracker = memoryTracker;
            _spillManager = spillManager;
            _maxMemoryBytes = maxMemoryBytes;

            for (int i = 0; i < PartitionCount; i++)
            {
                _partitions[i] = new PartitionBucket(i);
            }
        }

        private void InitializeSchemas(Schema inputSchema)
        {
            _inputSchema = inputSchema;
            _keyIndices = _groupByKeys.Select(k => _inputSchema.GetFieldIndex(k)).ToArray();
            _aggIndices = _aggDefinitions.Select(a => string.IsNullOrEmpty(a.TargetField) ? -1 : _inputSchema.GetFieldIndex(a.TargetField)).ToArray();

            var keyFields = _groupByKeys.Select(k => _inputSchema.Fields[_inputSchema.GetFieldIndex(k)]).ToList();
            _keySchema = new Schema(keyFields);

            var outputFields = new List<Field>(keyFields);
            foreach (var agg in _aggDefinitions)
            {
                DataType dType = agg.Type == AggregateType.Count ? DataType.Int : DataType.Double;
                outputFields.Add(new Field(agg.Alias, dType));
            }
            _outputSchema = new Schema(outputFields);
        }

        private IAggregateFunction CreateAggInstance(AggregateType type) => type switch
        {
            AggregateType.Sum => new SumAggregate(),
            AggregateType.Count => new CountAggregate(),
            _ => throw new NotSupportedException()
        };

        public async Task ConsumeAsync(ChannelReader<RecordBatch> inputReader)
        {
            while (await inputReader.WaitToReadAsync())
            {
                while (inputReader.TryRead(out var batch))
                {
                    if (_inputSchema == null)
                    {
                        InitializeSchemas(batch.Schema);
                    }

                    foreach (var record in batch.Records)
                    {
                        var keyValues = _keyIndices.Select(idx => record.Values[idx]).ToArray();
                        var key = new AggregateKey(keyValues);
                        int pId = Math.Abs(key.GetHashCode()) % PartitionCount;
                        var bucket = _partitions[pId];

                        if (bucket.IsSpilled)
                        {
                            // Route directly to disk without loading into RAM
                            var spillEntry = new DiskSpillEntry(record);
                            _spillManager.SpillEntry(bucket.PartitionId, spillEntry, _keySchema, _inputSchema);
                        }
                        else
                        {
                            long memDelta = 0;
                            if (!bucket.MemoryMap.TryGetValue(key, out var functions))
                            {
                                functions = _aggDefinitions.Select(a => CreateAggInstance(a.Type)).ToList();
                                bucket.MemoryMap[key] = functions;

                                // Estimate map metadata structures & key allocations
                                memDelta += MemoryTracker.EstimateRecordSize(new Record(key.Values)) + 64;
                                _memoryTracker.Allocate(memDelta);
                                bucket.BytesEstimated += memDelta;
                            }

                            for (int i = 0; i < functions.Count; i++)
                            {
                                var valIdx = _aggIndices[i];
                                var rawValue = valIdx == -1 ? null : record.Values[valIdx];
                                functions[i].Update(rawValue);
                            }

                            if (_memoryTracker.BytesAllocated > _maxMemoryBytes)
                            {
                                Console.WriteLine($"[Memory Warning] Buffer breached! Allocation limit: {_maxMemoryBytes} Bytes. Current: {_memoryTracker.BytesAllocated} Bytes.");
                                SpillLargestPartition();
                            }
                        }
                    }
                }
            }

            // Flush spill files to write buffers
            for (int i = 0; i < PartitionCount; i++)
            {
                if (_partitions[i].IsSpilled)
                {
                    _spillManager.FlushPartition(i);
                }
            }
        }

        private void SpillLargestPartition()
        {
            var target = _partitions
                .Where(p => !p.IsSpilled && p.MemoryMap.Count > 0)
                .OrderByDescending(p => p.BytesEstimated)
                .FirstOrDefault();

            if (target == null) return;

            Console.WriteLine($"[Spill Triggered] Flushing unspilled Partition {target.PartitionId} to disk freeing {target.BytesEstimated} estimated bytes...");

            foreach (var kv in target.MemoryMap)
            {
                var partialStates = kv.Value.Select(f => f.GetState()).ToArray();
                var spillEntry = new DiskSpillEntry(kv.Key, partialStates);
                _spillManager.SpillEntry(target.PartitionId, spillEntry, _keySchema, _inputSchema);
            }

            _spillManager.FlushPartition(target.PartitionId);
            _memoryTracker.Deallocate(target.BytesEstimated);
            target.MemoryMap.Clear();
            target.IsSpilled = true;
            target.BytesEstimated = 0;
        }

        public async IAsyncEnumerable<RecordBatch> GetResultsAsync()
        {
            for (int i = 0; i < PartitionCount; i++)
            {
                var bucket = _partitions[i];
                if (!bucket.IsSpilled)
                {
                    if (bucket.MemoryMap.Count > 0)
                    {
                        yield return FlushInMemoryBucket(bucket.MemoryMap);
                    }
                }
                else
                {
                    // Grace dynamic loading phase
                    Console.WriteLine($"[Grace Merge] Dynamic reloading and merging disk segment from Partition {bucket.PartitionId}...");
                    var localTable = new Dictionary<AggregateKey, List<IAggregateFunction>>();

                    foreach (var spillItem in _spillManager.StreamPartition(bucket.PartitionId, _keySchema, _inputSchema))
                    {
                        if (spillItem.IsPartialAggregate)
                        {
                            if (!localTable.TryGetValue(spillItem.Key, out var functions))
                            {
                                functions = _aggDefinitions.Select(a => CreateAggInstance(a.Type)).ToList();
                                localTable[spillItem.Key] = functions;
                            }
                            for (int fIdx = 0; fIdx < functions.Count; fIdx++)
                            {
                                functions[fIdx].Merge(spillItem.States[fIdx]);
                            }
                        }
                        else
                        {
                            var keyValues = _keyIndices.Select(idx => spillItem.RawRecord.Values[idx]).ToArray();
                            var key = new AggregateKey(keyValues);
                            if (!localTable.TryGetValue(key, out var functions))
                            {
                                functions = _aggDefinitions.Select(a => CreateAggInstance(a.Type)).ToList();
                                localTable[key] = functions;
                            }
                            for (int fIdx = 0; fIdx < functions.Count; fIdx++)
                            {
                                var valIdx = _aggIndices[fIdx];
                                var rawValue = valIdx == -1 ? null : spillItem.RawRecord.Values[valIdx];
                                functions[fIdx].Update(rawValue);
                            }
                        }
                    }

                    if (localTable.Count > 0)
                    {
                        yield return FlushInMemoryBucket(localTable);
                    }
                }
            }
        }

        private RecordBatch FlushInMemoryBucket(Dictionary<AggregateKey, List<IAggregateFunction>> aggMap)
        {
            var records = new List<Record>(aggMap.Count);
            foreach (var kv in aggMap)
            {
                var combinedValues = new object[_outputSchema.Fields.Count];
                Array.Copy(kv.Key.Values, combinedValues, kv.Key.Values.Length);
                int offset = kv.Key.Values.Length;
                for (int i = 0; i < kv.Value.Count; i++)
                {
                    combinedValues[offset + i] = kv.Value[i].Compute();
                }
                records.Add(new Record(combinedValues));
            }
            return new RecordBatch(_outputSchema, records);
        }
    }

